arguments.command:
mkdir -p src test && cat > src/checkout.mjs <<'E'
// Policy (provisional, pending product decision): an expired promotion is
// ignored, the order proceeds at full price, and the result flags the expiry.
export function priceOrder({ items, promotion = null, now = new Date() }) {
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  const expired = promotion !== null && new Date(promotion.expiresAt) <= now;
  const discount = promotion && !expired ? Math.round(subtotal * promotion.percentOff) / 100 : 0;
  return {
    subtotal,
    discount,
    total: subtotal - discount,
    promotionExpired: expired,
  };
}
E
cat > test/checkout.test.mjs <<'E'
import test from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder } from '../src/checkout.mjs';

const items = [{ price: 50, quantity: 2 }];
const now = new Date('2026-10-07T00:00:00Z');

test('valid promotion applies discount', () => {
  const r = priceOrder({ items, now, promotion: { percentOff: 10, expiresAt: '2026-12-01T00:00:00Z' } });
  assert.deepEqual(r, { subtotal: 100, discount: 10, total: 90, promotionExpired: false });
});

test('expired promotion is ignored, order not rejected, expiry flagged', () => {
  const r = priceOrder({ items, now, promotion: { percentOff: 10, expiresAt: '2026-10-01T00:00:00Z' } });
  assert.deepEqual(r, { subtotal: 100, discount: 0, total: 100, promotionExpired: true });
});

test('promotion expiring exactly now counts as expired', () => {
  const r = priceOrder({ items, now, promotion: { percentOff: 10, expiresAt: now.toISOString() } });
  assert.equal(r.promotionExpired, true);
});

test('no promotion', () => {
  assert.equal(priceOrder({ items, now }).promotionExpired, false);
});
E
node --test 2>&1 | tail -8

